css:
[data-bz-node="sh"]{color:#fff}
[data-bz-node="sh"] .bz-block{padding-block:0}
[data-bz-node="sh"] .bz-container{max-width:var(--container)}
[data-bz-node="sh-nav"]{display:flex;justify-content:flex-end}
[data-bz-node="sh-nav"] .bz-menu-wrap{flex:0 1 auto}
[data-bz-node="sh-nav"] .bz-menu-toggle{color:#fff;border-color:rgba(255,255,255,.4);background:rgb(26 23 20 / 55%)}
@media (min-width:1101px){
  [data-bz-node="sh-nav"] .bz-menu-wrap{background:rgb(26 23 20 / 55%);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);border-radius:var(--radius-nav);padding:6px 10px}
  [data-bz-node="sh-nav"] .bz-nav{gap:2px}
  [data-bz-node="sh-nav"] .bz-navitem > a{color:#fff;font:700 14px/1.2 var(--font-body);letter-spacing:.04em;text-transform:uppercase;padding:10px 14px;border-radius:7px}
  [data-bz-node="sh-nav"] .bz-navitem > a:hover{background:rgba(255,255,255,.1);color:#fff}
  [data-bz-node="sh-nav"] .bz-navitem > a[aria-current="page"]{color:var(--accent)}
  [data-bz-node="sh-nav"] .bz-subnav{top:calc(100% + 6px);left:0;padding:var(--space-2);min-width:12rem}
  [data-bz-node="sh-nav"] .bz-subnav .bz-navitem > a{color:var(--ink);text-transform:none;letter-spacing:0;font-weight:600;display:block}
  [data-bz-node="sh-nav"] .bz-subnav .bz-navitem > a:hover{background:var(--paper);color:var(--ink)}
}
@media (max-width:1100px){
  [data-bz-node="sh-nav"] .bz-menu-wrap[data-open] > .bz-menu{background:var(--ink);border-bottom:1px solid rgba(255,255,255,.16)}
  [data-bz-node="sh-nav"] .bz-menu-wrap[data-open] .bz-navitem > a{color:#fff;font:600 16px/1.3 var(--font-body);padding:var(--space-2) 0}
  [data-bz-node="sh-nav"] .bz-menu-wrap[data-open] .bz-subnav{background:none;border:0;box-shadow:none;position:static;display:flex}
  [data-bz-node="sh-nav"] .bz-menu-wrap[data-open] .bz-subnav .bz-navitem > a{color:#D8D2C4}
}
